#nullable enable

using JasperFx.Events;
using Marten;
using StockFeed.Contracts;

namespace StockFeed.Slices.StockFeed;

/// <summary>
/// THE DECIDER for <see cref="ApplyStockNotice"/> — it folds our stream, applies the rules, and appends the
/// event. Same job an HTTP endpoint does for a command somebody types, in a different transport.
///
/// A Wolverine MESSAGE handler and not an endpoint, because **nobody types this command**: the
/// <see cref="StockTranslator"/> trigger issues it. Giving it a route would invent public surface the model
/// does not draw.
///
/// EVERYTHING IT SEES IS ALREADY IN OUR VOCABULARY. The command carries <c>onHand</c>, not <c>quantity</c>;
/// the translation happened at the trigger. Nothing in this file or downstream of it knows the warehouse
/// exists, except for the notice id it carries as a correlation value.
///
/// TWO RULES, both needing accumulated state, so both enforce="aggregate":
///
///   AlreadyApplied  this notice has already been translated. THE LOAD-BEARING ONE — every landing mechanism
///                   is at-least-once and a black box that re-sends on reconnect makes a redelivery ordinary.
///   StaleNotice     the notice is older than the level we last accepted. Only some landing mechanisms can
///                   even produce this: a cursor-ordered poll cannot deliver out of order, a webhook or a
///                   queue can. The rule stays regardless, because the landing choice may change later.
///
/// A THIRD RULE WAS REMOVED, and its removal is a finding rather than a simplification. The model used to
/// carry "a notice nothing ever delivered cannot be applied" → <c>NoticeNotReceived</c>. That rule was only
/// expressible while the foreign notice was being persisted into our stream — it asked "is their event in our
/// history?", a question we should never be able to answer. Once the notice stopped being persisted the rule
/// had nothing to check, so it came off the model. It was an artifact of a wrong implementation choice that
/// had made its way back into the domain, which is the direction of contamination worth watching for.
/// </summary>
public static class ApplyStockNoticeHandler
{
    /// <summary>
    /// How many times to re-read and re-decide after losing a version race. Small, because a collision means
    /// another writer got there first and re-deciding is cheap; bounded, because a stream under permanent
    /// contention should surface as a failure rather than spin.
    /// </summary>
    private const int Attempts = 3;

    public static async Task<ApplyOutcome> Handle(
        ApplyStockNotice command,
        IDocumentSession session,
        CancellationToken cancellation)
    {
        for (var attempt = 1; ; attempt++)
        {
            var stream = await session.Events.FetchForWriting<TranslateStockNoticeState>(
                TranslateStockNoticeState.StreamKey(command.ProductId), cancellation);
            var stock = stream.Aggregate ?? new TranslateStockNoticeState();

            // ORDER IS LOAD-BEARING. A redelivery of the notice we last accepted satisfies BOTH conditions —
            // its sequence equals the accepted one — and the model names them as different rules with different
            // meanings. "You already told us this" is the truthful one; reporting StaleNotice would send a
            // caller looking for a clock problem.
            if (stock.HasApplied(command.NoticeId))
                return ApplyOutcome.Rejected("AlreadyApplied",
                    $"Notice {command.NoticeId} has already been translated. Every landing mechanism here is at-least-once, so this is the normal case rather than an error in the caller.");

            if (command.Sequence <= stock.AcceptedSequence)
                return ApplyOutcome.Rejected("StaleNotice",
                    $"Notice {command.NoticeId} carries sequence {command.Sequence}, and we have already accepted {stock.AcceptedSequence}. Across a boundary nothing guarantees arrival order, so an older notice is old news and not a correction.");

            // terminal="setAt:clock" — the model says so, and the handler is where a clock value enters.
            stream.AppendOne(new StockLevelSet(
                command.ProductId, command.NoticeId, command.OnHand, command.Sequence, DateTimeOffset.UtcNow));

            try
            {
                await session.SaveChangesAsync(cancellation);
                return ApplyOutcome.Accepted(command.ProductId, command.NoticeId, command.OnHand);
            }
            catch (EventStreamUnexpectedMaxEventIdException) when (attempt < Attempts)
            {
                // RE-READ AND RE-DECIDE. Now that only StockLevelSet is ever appended here, this stream has
                // exactly one writer — so the automation folder's shortcut of translating the collision into
                // AlreadyApplied would in fact be defensible. It is still not taken, because re-deciding is
                // cheap and returns the TRUE rule rather than an assumed one, and because the assumption stops
                // holding the moment anything else ever writes to the Stock stream. Asserting an invariant that
                // a future slice can silently break is how the first version of this folder went wrong.
                session.EjectAllPendingChanges();
            }
        }
    }
}

/// <summary>
/// What the decider answers with, and the reason it is not <c>ProblemDetails</c>: an automation has no HTTP
/// caller to hand one to. <see cref="Rule"/> carries the model's rule name verbatim, which is the invariant
/// that holds across every transport — a GWT says <c>then="error: StaleNotice"</c>, so the name is the
/// machine-readable half and the prose is for a human reading a log.
/// </summary>
public sealed record ApplyOutcome(Guid? ProductId, Guid? NoticeId, int? OnHand, string? Rule, string? Detail)
{
    public bool WasApplied => Rule is null;

    public static ApplyOutcome Accepted(Guid productId, Guid noticeId, int onHand) =>
        new(productId, noticeId, onHand, null, null);

    public static ApplyOutcome Rejected(string rule, string detail) => new(null, null, null, rule, detail);
}
